1	"use client";
2	
3	import { use, useCallback, useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { notFound, useRouter } from "next/navigation";
6	import { PageHeader } from "@/components/page-header";
7	import { Card, CardContent } from "@repo/ui/components/card";
8	import { Button } from "@repo/ui/components/button";
9	import { Badge } from "@repo/ui/components/badge";
10	import { Separator } from "@repo/ui/components/separator";
11	import { RiskBadge, StatusBadge } from "@/components/badges";
12	import { ActionCard } from "@/components/action-card";
13	import { useToast } from "@/components/toaster";
14	import { api, agentRun, ApiError, friendlyApiError } from "@/lib/api";
15	import { emit } from "@/lib/bus";
16	import type { AgentAction, Property, Ticket, Vendor } from "@/lib/types";
17	import { formatEur, timeAgo } from "@/lib/utils";
18	import { cn } from "@repo/ui/lib/utils";
19	import {
20	  Phone, Mail, ChevronDown, ChevronRight, Check, Sparkles,
21	  CheckCircle2, Clock, MessageSquare, Wrench, FileEdit, Loader2,
22	  Play, AlertTriangle, Bot,
23	} from "lucide-react";
24	
25	type Mutation = "approve" | "reject" | "saveMemory" | "skipMemory";
26	
27	export default function TicketDetailPage({ params }: { params: Promise<{ id: string }> }) {
28	  const { id } = use(params);
29	  const router = useRouter();
30	  const { push: pushToast } = useToast();
31	
32	  const [t, setTicket] = useState<Ticket | null>(null);
33	  const [prop, setProp] = useState<Property | null>(null);
34	  const [vendor, setVendor] = useState<Vendor | null>(null);
35	  const [loadError, setLoadError] = useState<string | null>(null);
36	  const [mutating, setMutating] = useState<Mutation | null>(null);
37	
38	  const [transcriptOpen, setTranscriptOpen] = useState(false);
39	  const [reasoningOpen, setReasoningOpen] = useState(false);
40	
41	  // -----------------------------------------------------------------------
42	  // Sprint 2: Streaming action cards state
43	  // -----------------------------------------------------------------------
44	  const [actions, setActions] = useState<AgentAction[]>([]);
45	  const [agentRunning, setAgentRunning] = useState(false);
46	  const [agentDone, setAgentDone] = useState(false);
47	  const [agentText, setAgentText] = useState("");
48	  const abortRef = useRef<AbortController | null>(null);
49	  const actionsEndRef = useRef<HTMLDivElement>(null);
50	
51	  // Load any existing actions for this ticket (from previous runs)
52	  useEffect(() => {
53	    let cancelled = false;
54	    api.tickets.actions(id).then((existing) => {
55	      if (!cancelled && existing.length > 0) {
56	        setActions(existing);
57	      }
58	    }).catch(() => {/* ignore — actions table may be empty */});
59	    return () => { cancelled = true; };
60	  }, [id]);
61	
62	  // Auto-scroll to bottom of actions stream
63	  useEffect(() => {
64	    actionsEndRef.current?.scrollIntoView({ behavior: "smooth" });
65	  }, [actions.length]);
66	
67	  function upsertAction(incoming: AgentAction) {
68	    setActions((prev) => {
69	      const idx = prev.findIndex((a) => a.id === incoming.id);
70	      if (idx >= 0) {
71	        const updated = [...prev];
72	        updated[idx] = incoming;
73	        return updated;
74	      }
75	      return [...prev, incoming];
76	    });
77	  }
78	
79	  async function startAgentRun() {
80	    if (agentRunning) return;
81	    setAgentRunning(true);
82	    setAgentDone(false);
83	    setAgentText("");
84	
85	    const ctrl = new AbortController();
86	    abortRef.current = ctrl;
87	
88	    try {
89	      await agentRun.stream(
90	        id,
91	        {
92	          onActionCard: upsertAction,
93	          onDelta: (text) => setAgentText((s) => s + text),
94	          onDone: () => {
95	            setAgentDone(true);
96	            // Refetch ticket in case escalation changed the risk level
97	            refetchTicket();
98	          },
99	          onError: (err) => {
100	            pushToast({
101	              title: "Agent run failed",
102	              description: err instanceof Error ? err.message : String(err),
103	              variant: "destructive",
104	            });
105	          },
106	          signal: ctrl.signal,
107	        }
108	      );
109	    } catch (err) {
110	      if (err instanceof Error && err.name === "AbortError") return;
111	    } finally {
112	      setAgentRunning(false);
113	    }
114	  }
115	
116	  function stopAgentRun() {
117	    abortRef.current?.abort();
118	    setAgentRunning(false);
119	  }
120	
121	  // -----------------------------------------------------------------------
122	  // Ticket loading
123	  // -----------------------------------------------------------------------
124	
125	  useEffect(() => {
126	    let cancelled = false;
127	    setTicket(null);
128	    setProp(null);
129	    setVendor(null);
130	    setLoadError(null);
131	    (async () => {
132	      try {
133	        const ticket = await api.tickets.get(id);
134	        if (cancelled) return;
135	        setTicket(ticket);
136	        const [property, v] = await Promise.all([
137	          api.properties.get(ticket.propertyId),
138	          ticket.proposal ? api.vendors.get(ticket.proposal.proposedAction.vendorId) : Promise.resolve(null),
139	        ]);
140	        if (cancelled) return;
141	        setProp(property);
142	        setVendor(v);
143	      } catch (err) {
144	        if (cancelled) return;
145	        if (err instanceof ApiError && err.status === 404) {
146	          notFound();
147	          return;
148	        }
149	        setLoadError(err instanceof Error ? err.message : "Failed to load ticket");
150	      }
151	    })();
152	    return () => { cancelled = true; };
153	  }, [id]);
154	
155	  async function runMutation(
156	    kind: Mutation,
157	    fn: () => Promise<void>,
158	  ) {
159	    setMutating(kind);
160	    try {
161	      await fn();
162	    } catch (err) {
163	      const friendly = friendlyApiError(err, kind);
164	      pushToast({ ...friendly, variant: "destructive" });
165	    } finally {
166	      setMutating(null);
167	    }
168	  }
169	
170	  async function refetchTicket(): Promise<Ticket | null> {
171	    try {
172	      const fresh = await api.tickets.get(id);
173	      setTicket(fresh);
174	      return fresh;
175	    } catch (err) {
176	      const friendly = friendlyApiError(err, "load");
177	      pushToast({ ...friendly, variant: "destructive" });
178	      return null;
179	    }
180	  }
181	
182	  async function handleApprove() {
183	    if (!t) return;
184	    await runMutation("approve", async () => {
185	      await api.tickets.approve(t.id);
186	      const fresh = await refetchTicket();
187	      pushToast({
188	        title: "Dispatch approved",
189	        description: fresh?.vendorJob ? `SLA timer started · status ${fresh.status}` : "SMS sent to vendor.",
190	        variant: "success",
191	      });
192	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
193	      router.refresh();
194	    });
195	  }
196	
197	  async function handleReject() {
198	    if (!t) return;
199	    await runMutation("reject", async () => {
200	      await api.tickets.reject(t.id);
201	      await refetchTicket();
202	      pushToast({ title: "Proposal rejected" });
203	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
204	      router.refresh();
205	    });
206	  }
207	
208	  async function handleSaveMemory() {
209	    if (!t || !t.memoryProposal) return;
210	    await runMutation("saveMemory", async () => {
211	      const result = await api.tickets.saveMemory(t.id);
212	      await refetchTicket();
213	      pushToast({
214	        title: "Memory saved",
215	        description: `context.md bumped to v${result.contextVersion}`,
216	        variant: "success",
217	      });
218	      emit({ kind: "context-bumped", propertyId: t.propertyId, version: result.contextVersion });
219	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
220	      router.refresh();
221	    });
222	  }
223	
224	  async function handleSkipMemory() {
225	    if (!t || !t.memoryProposal) return;
226	    await runMutation("skipMemory", async () => {
227	      await api.tickets.skipMemory(t.id);
228	      await refetchTicket();
229	      pushToast({ title: "Memory write skipped" });
230	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
231	      router.refresh();
232	    });
233	  }
234	
235	  if (loadError) {
236	    return <div className="p-8 text-sm text-destructive">{loadError}</div>;
237	  }
238	  if (!t) {
239	    return <TicketDetailSkeleton />;
240	  }
241	
242	  const isApproved = t.status !== "proposed" && t.status !== "new" && t.status !== "triaged" && t.status !== "rejected";
243	  const memorySaved = t.memoryProposal?.status === "saved";
244	  const memorySkipped = t.memoryProposal?.status === "skipped";
245	  const showMemoryDecision =
246	    !!t.memoryProposal &&
247	    t.memoryProposal.status === "pending" &&
248	    !!t.vendorJob?.completedAt;
249	
250	  // Sprint 2: is this ticket escalated?
251	  const isEscalated = !!t.escalatedAt || t.risk === "high";
252	
253	  return (
254	    <div>
255	      <PageHeader
256	        title={t.subject}
257	        subtitle={`${prop?.name ?? ""} · ${t.raisedBy} · ${timeAgo(t.createdAt)} ago`}
258	        crumbs={[{ label: "Properties" }, { label: prop?.name ?? "", href: prop ? `/property/${prop.id}/tickets` : undefined }, { label: t.num }]}
259	        actions={
260	          <div className="flex items-center gap-2">
261	            <StatusBadge status={t.status} />
262	            <RiskBadge risk={t.risk} />
263	            {t.escalatedAt && (
264	              <Badge variant="destructive" className="text-xs">
265	                <AlertTriangle className="mr-1 h-3 w-3" /> Escalated
266	              </Badge>
267	            )}
268	            <span className="font-mono text-xs text-muted-foreground">{t.num}</span>
269	          </div>
270	        }
271	      />
272	
273	      <div className="grid grid-cols-3 gap-6 p-8">
274	        {/* LEFT 2/3 — proposal-first */}
275	        <div className="col-span-2 space-y-4">
276	          {/* Proposal card (only shown when proposed) */}
277	          {t.proposal && (
278	            <Card className="border-blue-500/30 bg-blue-500/5">
279	              <CardContent className="p-5">
280	                <div className="mb-3 flex items-center justify-between">
281	                  <div className="text-xs font-semibold uppercase tracking-wider text-blue-500 dark:text-blue-400">
282	                    Proposed action <span className="ml-2 font-mono text-muted-foreground">{t.proposal.id}</span>
283	                  </div>
284	                  <Badge variant="muted" className="font-mono">conf {Math.round(t.proposal.confidence * 100)}%</Badge>
285	                </div>
286	
287	                {/* Action — vendor / cost / ETA */}
288	                <div className="mb-4 flex items-start justify-between gap-6">
289	                  <div className="min-w-0 flex-1">
290	                    <div className="text-xl font-semibold">{t.proposal.proposedAction.vendor}</div>
291	                    <div className="text-sm text-muted-foreground">
292	                      {t.proposal.proposedAction.trade} · {t.proposal.proposedAction.target}
293	                    </div>
294	                  </div>
295	                  <div className="flex shrink-0 items-stretch gap-2">
296	                    <div className="rounded-md border bg-background px-3 py-2 text-center">
297	                      <div className="text-lg font-semibold leading-none">{formatEur(t.proposal.proposedAction.estimateEur)}</div>
298	                      <div className="mt-1 text-[10px] text-muted-foreground">estimate</div>
299	                    </div>
300	                    <div className="rounded-md border bg-background px-3 py-2 text-center">
301	                      <div className="text-lg font-semibold leading-none">{t.proposal.proposedAction.etaHours}h</div>
302	                      <div className="mt-1 text-[10px] text-muted-foreground">ETA</div>
303	                    </div>
304	                  </div>
305	                </div>
306	
307	                {/* Policy chips */}
308	                <div className="mb-4 flex flex-wrap gap-1.5">
309	                  {t.proposal.policiesEvaluated.map((p) => (
310	                    <Badge key={p.code} variant={p.passed ? "success" : "destructive"} className="font-normal">
311	                      {p.passed ? "✓" : "✗"} {p.name}
312	                    </Badge>
313	                  ))}
314	                </div>
315	
316	                {/* Consequences */}
317	                <div className="mb-4 rounded-md border border-emerald-500/30 bg-emerald-500/8 p-4">
318	                  <div className="mb-2 text-[10px] font-semibold uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Approving will:</div>
319	                  <ul className="space-y-1.5 text-sm">
320	                    <li className="flex gap-2"><span>→</span><span>Dispatch <strong>{t.proposal.proposedAction.vendor}</strong> to {t.proposal.proposedAction.target}</span></li>
321	                    <li className="flex gap-2"><span>→</span><span>Send written confirmation to {t.raisedBy} <em>(Sie-Form, mobility flag respected)</em></span></li>
322	                    <li className="flex gap-2"><span>→</span><span>Send SMS dispatch to {vendor?.name ?? t.proposal.proposedAction.vendor} ({vendor?.phone ?? "—"}) — {vendor?.slaHours ?? t.proposal.proposedAction.etaHours}h SLA timer starts</span></li>
323	                    <li className="flex gap-2 text-muted-foreground"><span>→</span><span>Memory write happens <strong>after</strong> vendor reports completion (not now)</span></li>
324	                  </ul>
325	                </div>
326	
327	                {/* Action row */}
328	                {!isApproved && t.status === "proposed" ? (
329	                  <div className="flex items-center gap-2">
330	                    <Button
331	                      variant="success"
332	                      className="flex-1"
333	                      onClick={handleApprove}
334	                      disabled={mutating !== null}
335	                    >
336	                      {mutating === "approve" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
337	                      Approve dispatch
338	                    </Button>
339	                    <Button variant="outline" disabled={mutating !== null}>Edit</Button>
340	                    <Button
341	                      variant="ghost"
342	                      className="text-red-600 hover:bg-red-50 hover:text-red-700"
343	                      onClick={handleReject}
344	                      disabled={mutating !== null}
345	                    >
346	                      {mutating === "reject" ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
347	                      Reject
348	                    </Button>
349	                  </div>
350	                ) : isApproved ? (
351	                  <div className="rounded-md border border-emerald-500/40 bg-emerald-500/10 p-3 text-sm">
352	                    <div className="flex items-center gap-2 font-medium text-emerald-600 dark:text-emerald-400">
353	                      <CheckCircle2 className="h-4 w-4" />
354	                      Dispatch approved · SMS sent to {vendor?.name ?? t.proposal.proposedAction.vendor} · Email sent to {t.raisedBy}
355	                    </div>
356	                    <div className="mt-1 text-xs text-emerald-600/80 dark:text-emerald-400/80">
357	                      SLA timer started ({vendor?.slaHours ?? t.proposal.proposedAction.etaHours}h). Status: <strong>{t.status}</strong>. No memory write yet.
358	                    </div>
359	                  </div>
360	                ) : t.status === "rejected" ? (
361	                  <div className="rounded-md border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive">
362	                    Proposal rejected.
363	                  </div>
364	                ) : null}
365	
366	                {/* Reasoning collapsed by default */}
367	                <button
368	                  onClick={() => setReasoningOpen((o) => !o)}
369	                  className="mt-4 flex w-full items-center justify-between rounded-md border-t pt-3 text-left text-sm hover:bg-accent/50"
370	                >
371	                  <span className="font-medium">Reasoning & evidence <span className="ml-1 font-mono text-xs text-muted-foreground">cites context.md v{t.proposal.contextVersion}</span></span>
372	                  {reasoningOpen ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
373	                </button>
374	                {reasoningOpen && (
375	                  <div className="mt-3 space-y-3 text-sm">
376	                    <p className="text-muted-foreground">{t.proposal.reasoning}</p>
377	                    <div className="space-y-2">
378	                      {t.proposal.citations.map((c, i) => (
379	                        <div key={i} className="rounded border-l-2 border-blue-300 bg-background px-3 py-2">
380	                          <div className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">{c.heading}</div>
381	                          <div className="text-sm">{c.excerpt}</div>
382	                        </div>
383	                      ))}
384	                    </div>
385	                  </div>
386	                )}
387	              </CardContent>
388	            </Card>
389	          )}
390	
391	          {/* ================================================================
392	              Sprint 2: AGENT ACTION STREAM
393	              Shows a live stream of what Hermes is doing / has proposed.
394	              ================================================================ */}
395	          <Card className="overflow-hidden">
396	            <CardContent className="p-0">
397	              {/* Header */}
398	              <div className="flex items-center justify-between border-b px-5 py-3">
399	                <div className="flex items-center gap-2">
400	                  <Bot className="h-4 w-4 text-blue-500" />
401	                  <span className="text-sm font-semibold">Hermes agent actions</span>
402	                  {agentRunning && (
403	                    <Badge variant="muted" className="animate-pulse text-xs">
404	                      <Loader2 className="mr-1 h-3 w-3 animate-spin" />
405	                      running…
406	                    </Badge>
407	                  )}
408	                  {agentDone && !agentRunning && actions.length > 0 && (
409	                    <Badge variant="success" className="text-xs">
410	                      <CheckCircle2 className="mr-1 h-3 w-3" />
411	                      complete
412	                    </Badge>
413	                  )}
414	                </div>
415	                {agentRunning ? (
416	                  <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={stopAgentRun}>
417	                    Stop
418	                  </Button>
419	                ) : (
420	                  <Button
421	                    size="sm"
422	                    variant="outline"
423	                    className="h-7 text-xs gap-1"
424	                    onClick={startAgentRun}
425	                    disabled={agentRunning}
426	                  >
427	                    <Play className="h-3 w-3" />
428	                    {actions.length > 0 ? "Re-run Hermes" : "Run Hermes"}
429	                  </Button>
430	                )}
431	              </div>
432	
433	              {/* Action cards stream */}
434	              {actions.length === 0 && !agentRunning ? (
435	                <div className="p-8 text-center text-sm text-muted-foreground">
436	                  <Bot className="mx-auto mb-2 h-6 w-6 opacity-30" />
437	                  <p>Click <strong>Run Hermes</strong> to have the agent analyse this ticket</p>
438	                  <p className="mt-1 text-xs">
439	                    The agent will read property context, check policies, and propose appropriate actions.
440	                  </p>
441	                </div>
442	              ) : (
443	                <div className="max-h-[600px] overflow-auto p-4 space-y-2">
444	                  {actions.map((action) => (
445	                    <div
446	                      key={action.id}
447	                      className="animate-in fade-in slide-in-from-bottom-2 duration-300"
448	                    >
449	                      <ActionCard
450	                        action={action}
451	                        onConfirmed={() => refetchTicket()}
452	                      />
453	                    </div>
454	                  ))}
455	
456	                  {/* Agent reasoning text (streaming) */}
457	                  {agentText && (
458	                    <Card className="border-muted/50 bg-muted/20">
459	                      <CardContent className="p-3 text-xs text-muted-foreground leading-relaxed whitespace-pre-wrap">
460	                        <span className="font-semibold text-foreground">Hermes: </span>
461	                        {agentText}
462	                        {agentRunning && <span className="inline-block h-3 w-0.5 animate-pulse bg-foreground ml-0.5" />}
463	                      </CardContent>
464	                    </Card>
465	                  )}
466	
467	                  <div ref={actionsEndRef} />
468	                </div>
469	              )}
470	            </CardContent>
471	          </Card>
472	
473	          {/* ================================================================
474	              Escalation notice (Sprint 2)
475	              ================================================================ */}
476	          {t.escalatedAt && (
477	            <Card className="border-destructive/40 bg-destructive/5">
478	              <CardContent className="p-4">
479	                <div className="flex items-start gap-2">
480	                  <AlertTriangle className="mt-0.5 h-4 w-4 text-destructive" />
481	                  <div>
482	                    <div className="text-sm font-semibold text-destructive">Escalated to human operator</div>
483	                    <div className="mt-1 text-xs text-muted-foreground whitespace-pre-wrap">{t.escalationReason}</div>
484	                  </div>
485	                </div>
486	              </CardContent>
487	            </Card>
488	          )}
489	
490	          {/* Vendor job status (when in flight or completed) */}
491	          {t.vendorJob && (
492	            <Card>
493	              <CardContent className="p-5">
494	                <div className="mb-3 flex items-center gap-2">
495	                  <Wrench className="h-4 w-4 text-muted-foreground" />
496	                  <h3 className="text-sm font-semibold">Vendor job</h3>
497	                </div>
498	                <ul className="space-y-2 text-sm">
499	                  <li className="flex justify-between"><span className="text-muted-foreground">Sent</span><span>{new Date(t.vendorJob.sentAt).toLocaleString("de-DE")}</span></li>
500	                  <li className="flex justify-between"><span className="text-muted-foreground">Accepted</span><span>{t.vendorJob.accepted ? "Yes" : "Pending"}</span></li>
501	                  {t.vendorJob.scheduledFor && <li className="flex justify-between"><span className="text-muted-foreground">Scheduled</span><span>{new Date(t.vendorJob.scheduledFor).toLocaleString("de-DE")}</span></li>}
502	                  {t.vendorJob.completedAt && <li className="flex justify-between"><span className="text-muted-foreground">Completed</span><span>{new Date(t.vendorJob.completedAt).toLocaleString("de-DE")}</span></li>}
503	                  {t.vendorJob.finalCostEur != null && <li className="flex justify-between"><span className="text-muted-foreground">Final cost</span><span className="font-medium">{formatEur(t.vendorJob.finalCostEur)}</span></li>}
504	                  {t.vendorJob.notes && <li className="text-muted-foreground">"{t.vendorJob.notes}"</li>}
505	                </ul>
506	              </CardContent>
507	            </Card>
508	          )}
509	
510	          {/* MEMORY DECISION — only after vendor completion AND status === pending */}
511	          {showMemoryDecision && (
512	            <Card className="border-emerald-500/30 bg-emerald-500/5">
513	              <CardContent className="p-5">
514	                <div className="mb-2 flex items-center gap-2">
515	                  <Sparkles className="h-4 w-4 text-emerald-500" />
516	                  <div className="text-xs font-semibold uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Memory decision · vendor closed the job</div>
517	                </div>
518	                <p className="mb-3 text-sm">
519	                  Save to <code className="font-mono text-xs">context.md v{t.memoryProposal!.targetVersion}</code>:
520	                </p>
521	                <blockquote className="mb-4 rounded border-l-2 border-emerald-400 bg-background px-3 py-2 text-sm">
522	                  {t.memoryProposal!.text}
523	                </blockquote>
524	                <div className="flex gap-2">
525	                  <Button variant="success" onClick={handleSaveMemory} disabled={mutating !== null}>
526	                    {mutating === "saveMemory" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
527	                    Save to memory
528	                  </Button>
529	                  <Button variant="outline" disabled={mutating !== null}><FileEdit className="h-4 w-4" />Edit</Button>
530	                  <Button variant="ghost" onClick={handleSkipMemory} disabled={mutating !== null}>
531	                    {mutating === "skipMemory" ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
532	                    Skip
533	                  </Button>
534	                </div>
535	              </CardContent>
536	            </Card>
537	          )}
538	
539	          {memorySaved && (
540	            <Card className="border-emerald-500/40 bg-emerald-500/10">
541	              <CardContent className="p-4 text-sm text-emerald-600 dark:text-emerald-400">
542	                <CheckCircle2 className="mr-2 inline h-4 w-4" />
543	                Memory saved to <code className="font-mono text-xs">context.md v{t.memoryProposal?.targetVersion}</code>. Ticket resolved.
544	              </CardContent>
545	            </Card>
546	          )}
547	
548	          {memorySkipped && (
549	            <Card>
550	              <CardContent className="p-4 text-sm text-muted-foreground">
551	                Memory write skipped. Ticket closed without context update.
552	              </CardContent>
553	            </Card>
554	          )}
555	
556	          {/* SOURCE — call transcript or email */}
557	          {t.callSession && (
558	            <Card>
559	              <CardContent className="p-5">
560	                <button
561	                  onClick={() => setTranscriptOpen((o) => !o)}
562	                  className="flex w-full items-center justify-between text-left"
563	                >
564	                  <div className="flex items-center gap-2">
565	                    <Phone className="h-4 w-4 text-muted-foreground" />
566	                    <span className="text-sm font-semibold">Call transcript</span>
567	                    <Badge variant="muted" className="font-mono">{t.callSession.duration}</Badge>
568	                    <span className="text-xs text-muted-foreground">noise reduction {t.callSession.noiseReductionDb} dB</span>
569	                  </div>
570	                  {transcriptOpen ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
571	                </button>
572	                {!transcriptOpen && (
573	                  <p className="mt-2 text-sm text-muted-foreground">{t.callSession.summary}</p>
574	                )}
575	                {transcriptOpen && (
576	                  <div className="mt-4 space-y-2 max-h-80 overflow-auto rounded border bg-muted/20 p-3">
577	                    {t.callSession.transcript.map((line, i) => (
578	                      <div key={i} className={cn("flex gap-3 text-sm", line.spk === "tenant" ? "" : "text-muted-foreground")}>
579	                        <span className="w-12 shrink-0 font-mono text-[10px] text-muted-foreground">{line.t}</span>
580	                        <span className="w-14 shrink-0 text-[10px] uppercase">{line.spk}</span>
581	                        <div className="flex-1">
582	                          <div>{line.text}</div>
583	                          <div className="text-[11px] italic text-muted-foreground">{line.en}</div>
584	                        </div>
585	                      </div>
586	                    ))}
587	                  </div>
588	                )}
589	              </CardContent>
590	            </Card>
591	          )}
592	
593	          {t.emailBody && (
594	            <Card>
595	              <CardContent className="p-5">
596	                <div className="mb-2 flex items-center gap-2">
597	                  <Mail className="h-4 w-4 text-muted-foreground" />
598	                  <span className="text-sm font-semibold">Email</span>
599	                </div>
600	                <pre className="whitespace-pre-wrap text-sm font-sans">{t.emailBody}</pre>
601	              </CardContent>
602	            </Card>
603	          )}
