1	"use client";
2	
3	/**
4	 * ActionCard — displays a single agent action as a streaming card in the ticket detail page.
5	 *
6	 * Status lifecycle:
7	 *   thinking  → animated spinner (agent is calling the tool)
8	 *   completed → checkmark (read tool returned data)
9	 *   proposed  → action-specific UI with confirm/reject (write tool proposal)
10	 *   confirmed → green confirmed badge
11	 *   rejected  → muted rejected badge
12	 */
13	
14	import { useState, useEffect } from "react";
15	import { Card, CardContent } from "@repo/ui/components/card";
16	import { Badge } from "@repo/ui/components/badge";
17	import { Button } from "@repo/ui/components/button";
18	import { cn } from "@repo/ui/lib/utils";
19	import {
20	  Loader2,
21	  Check,
22	  CheckCircle2,
23	  XCircle,
24	  Search,
25	  Mail,
26	  MessageSquare,
27	  FileBarChart2,
28	  AlertTriangle,
29	  ChevronDown,
30	  ChevronRight,
31	  User,
32	  Wrench,
33	  Brain,
34	} from "lucide-react";
35	import type { AgentAction, ActionProposalEnvelope } from "@/lib/types";
36	import { confirmAction, friendlyApiError } from "@/lib/api";
37	import { useToast } from "@/components/toaster";
38	
39	// ---------------------------------------------------------------------------
40	// Icon mapping per tool / action type
41	// ---------------------------------------------------------------------------
42	function ActionIcon({ toolName, className }: { toolName: string | null; className?: string }) {
43	  const cls = cn("h-4 w-4", className);
44	  switch (toolName) {
45	    case "send_vendor_email":        return <Mail className={cls} />;
46	    case "respond_to_tenant":        return <MessageSquare className={cls} />;
47	    case "send_owner_report":        return <FileBarChart2 className={cls} />;
48	    case "escalate_to_human":        return <AlertTriangle className={cls} />;
49	    case "approve_ticket":
50	    case "reject_ticket":            return <Wrench className={cls} />;
51	    case "get_property_context":
52	    case "get_property":             return <Brain className={cls} />;
53	    case "get_vendor":
54	    case "list_vendors":             return <Wrench className={cls} />;
55	    case "get_owner":                return <User className={cls} />;
56	    case "list_tickets":
57	    case "get_ticket":
58	    case "list_escalations":         return <Search className={cls} />;
59	    default:                         return <Search className={cls} />;
60	  }
61	}
62	
63	// ---------------------------------------------------------------------------
64	// Status badge
65	// ---------------------------------------------------------------------------
66	function StatusBadgeLocal({ status }: { status: AgentAction["status"] }) {
67	  switch (status) {
68	    case "thinking":
69	      return (
70	        <span className="flex items-center gap-1 text-xs text-muted-foreground">
71	          <Loader2 className="h-3 w-3 animate-spin" /> thinking…
72	        </span>
73	      );
74	    case "completed":
75	      return (
76	        <span className="flex items-center gap-1 text-xs text-emerald-600 dark:text-emerald-400">
77	          <CheckCircle2 className="h-3 w-3" /> done
78	        </span>
79	      );
80	    case "proposed":
81	      return <Badge variant="outline" className="text-xs border-amber-500/50 text-amber-600">proposed</Badge>;
82	    case "confirmed":
83	      return <Badge variant="success" className="text-xs">confirmed</Badge>;
84	    case "rejected":
85	      return <Badge variant="muted" className="text-xs line-through">rejected</Badge>;
86	    default:
87	      return null;
88	  }
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Proposal detail rendering (action-type specific)
93	// ---------------------------------------------------------------------------
94	function ProposalDetail({ proposal, toolName }: {
95	  proposal: ActionProposalEnvelope;
96	  toolName: string | null;
97	}) {
98	  if (toolName === "send_vendor_email" && proposal.email) {
99	    const e = proposal.email;
100	    return (
101	      <div className="mt-3 rounded-md border bg-background p-3 text-sm">
102	        <div className="mb-1 text-xs text-muted-foreground">
103	          <span className="font-medium">To:</span> {e.vendorName} &lt;{e.to}&gt;
104	        </div>
105	        <div className="mb-2 text-xs text-muted-foreground">
106	          <span className="font-medium">Subject:</span> {e.subject}
107	        </div>
108	        <pre className="whitespace-pre-wrap font-sans text-xs leading-relaxed">{e.body}</pre>
109	      </div>
110	    );
111	  }
112	
113	  if (toolName === "respond_to_tenant" && proposal.response) {
114	    const r = proposal.response;
115	    return (
116	      <div className="mt-3 rounded-md border bg-background p-3 text-sm">
117	        <div className="mb-2 flex items-center gap-2 text-xs text-muted-foreground">
118	          <Badge variant="muted" className="text-xs">{r.channelLabel}</Badge>
119	          <span>to {r.tenantName}</span>
120	        </div>
121	        <pre className="whitespace-pre-wrap font-sans text-xs leading-relaxed">{r.body}</pre>
122	      </div>
123	    );
124	  }
125	
126	  if (toolName === "send_owner_report" && proposal.report) {
127	    const r = proposal.report;
128	    return (
129	      <div className="mt-3 rounded-md border bg-background p-3 text-sm">
130	        <div className="mb-1 text-xs text-muted-foreground">
131	          <span className="font-medium">To:</span> {r.ownerName} &lt;{r.recipient}&gt;
132	        </div>
133	        <div className="mb-2 flex items-center gap-2 text-xs text-muted-foreground">
134	          <Badge variant="muted" className="text-xs">{r.formatLabel}</Badge>
135	        </div>
136	        <pre className="whitespace-pre-wrap font-sans text-xs leading-relaxed">{r.content}</pre>
137	      </div>
138	    );
139	  }
140	
141	  if (toolName === "escalate_to_human" && proposal.escalation) {
142	    const e = proposal.escalation;
143	    return (
144	      <div className="mt-3 space-y-2 rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm">
145	        <div>
146	          <div className="text-xs font-semibold uppercase tracking-wider text-destructive/80">Reason</div>
147	          <p className="text-sm">{e.reason}</p>
148	        </div>
149	        {e.triggeringPolicy && (
150	          <div>
151	            <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Triggering policy</div>
152	            <p className="text-sm text-muted-foreground">{e.triggeringPolicy}</p>
153	          </div>
154	        )}
155	        {e.recommendation && (
156	          <div>
157	            <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Recommended action</div>
158	            <p className="text-sm">{e.recommendation}</p>
159	          </div>
160	        )}
161	      </div>
162	    );
163	  }
164	
165	  // Fallback: show raw label
166	  return null;
167	}
168	
169	// ---------------------------------------------------------------------------
170	// Main ActionCard component
171	// ---------------------------------------------------------------------------
172	interface ActionCardProps {
173	  action: AgentAction;
174	  onConfirmed?: (actionId: string) => void;
175	  onRejected?: (actionId: string) => void;
176	  className?: string;
177	}
178	
179	export function ActionCard({ action, onConfirmed, onRejected, className }: ActionCardProps) {
180	  const [open, setOpen] = useState(false);
181	  const [confirming, setConfirming] = useState(false);
182	  const [rejecting, setRejecting] = useState(false);
183	  const [localStatus, setLocalStatus] = useState(action.status);
184	  const { push: pushToast } = useToast();
185	
186	  // Bug-004 fix: sync localStatus when the parent re-renders with an updated status
187	  // (e.g., action_proposal SSE fires and parent updates action.status from "thinking" → "proposed")
188	  useEffect(() => {
189	    // Only sync upward transitions — don't overwrite user-confirmed/rejected state
190	    if (localStatus !== "confirmed" && localStatus !== "rejected") {
191	      setLocalStatus(action.status);
192	    }
193	  }, [action.status]);
194	
195	  const proposal = action.payload?.proposal as ActionProposalEnvelope | undefined;
196	  const isProposed = localStatus === "proposed";
197	  const isRead = action.actionType === "read";
198	  const isWrite = !isRead && action.actionType !== "write_proposal";
199	  const hasConfirmEndpoint = !!proposal?.confirmEndpoint;
200	
201	  async function handleConfirm() {
202	    if (!proposal?.confirmEndpoint) return;
203	    setConfirming(true);
204	    try {
205	      await confirmAction(proposal);
206	      setLocalStatus("confirmed");
207	      pushToast({ title: "Action confirmed", variant: "success" });
208	      onConfirmed?.(action.id);
209	    } catch (err) {
210	      const { title, description } = friendlyApiError(err, "approve");
211	      pushToast({ title, description, variant: "destructive" });
212	    } finally {
213	      setConfirming(false);
214	    }
215	  }
216	
217	  function handleReject() {
218	    setLocalStatus("rejected");
219	    onRejected?.(action.id);
220	  }
221	
222	  // Border/bg color by action type
223	  const cardVariant = cn(
224	    "transition-all duration-300",
225	    action.toolName === "escalate_to_human" && localStatus !== "rejected"
226	      ? "border-destructive/30 bg-destructive/5"
227	      : action.toolName === "send_vendor_email" ||
228	        action.toolName === "respond_to_tenant" ||
229	        action.toolName === "send_owner_report"
230	      ? "border-amber-500/30 bg-amber-500/5"
231	      : isRead
232	      ? "border-border/50 bg-muted/20"
233	      : "border-blue-500/20 bg-blue-500/5",
234	    className
235	  );
236	
237	  return (
